if(!$profile || (int)($profile['profile_completed']??0)!==1){header('Location: '.($expected_role.'_profile.php'));exit;}
$counts=['offers'=>0,'requests'=>0,'directory'=>0];
if($stmt=$conn->prepare("SELECT COUNT(*) c FROM stakeholder_offers WHERE provider_id=?")){ $stmt->bind_param('i',$uid);$stmt->execute();$counts['offers']=(int)$stmt->get_result()->fetch_assoc()['c'];$stmt->close(); }
if($stmt=$conn->prepare("SELECT COUNT(*) c FROM stakeholder_offer_requests r INNER JOIN stakeholder_offers o ON o.id=r.offer_id WHERE o.provider_id=? AND r.status='pending'")){ $stmt->bind_param('i',$uid);$stmt->execute();$counts['requests']=(int)$stmt->get_result()->fetch_assoc()['c'];$stmt->close(); }
if($stmt=$conn->prepare("SELECT COUNT(*) c FROM stakeholder_profiles WHERE role<>? AND verification_status='verified'")){ $stmt->bind_param('s',$expected_role);$stmt->execute();$counts['directory']=(int)$stmt->get_result()->fetch_assoc()['c'];$stmt->close(); }
